#define DDR_CTRL_REGS_CTRL_RESET 0x00000000u
#define DDR_CTRL_REGS_STATUS_OFFSET 0x14u   /* RO */
#define DDR_CTRL_REGS_STATUS_RESET 0x00000000u
#define DDR_CTRL_REGS_RD_BEATS_OFFSET 0x18u   /* RO */
#define DDR_CTRL_REGS_RD_BEATS_RESET 0x00000000u
#define DDR_CTRL_REGS_WR_BEATS_OFFSET 0x1Cu   /* RO */
#define DDR_CTRL_REGS_WR_BEATS_RESET 0x00000000u
#define DDR_CTRL_REGS_ACTS_OFFSET 0x20u   /* RO */
#define DDR_CTRL_REGS_ACTS_RESET 0x00000000u
#define DDR_CTRL_REGS_HITS_OFFSET 0x24u   /* RO */
#define DDR_CTRL_REGS_HITS_RESET 0x00000000u
#define DDR_CTRL_REGS_REFS_OFFSET 0x28u   /* RO */
#define DDR_CTRL_REGS_REFS_RESET 0x00000000u
#define DDR_CTRL_REGS_ERRS_OFFSET 0x2Cu   /* RO */
#define DDR_CTRL_REGS_ERRS_RESET 0x00000000u
#endif /* DDR_CTRL_REGS_H */
